-- Seed script for 100 mock properties
-- Run this manually after initial migration: psql -U postgres -d realestatedb -f seed_properties.sql
-- Or in your SQL client

-- Insert 100 properties with realistic Vietnamese real estate data

-- Insert property images (5 images per property)
SELECT p.id, '/images/properties/property-' || p.id || '-' || s.img_num || '.jpg'
FROM properties p
CROSS JOIN (SELECT generate_series(1, 5) AS img_num) s
WHERE p.id <= 100;

-- Insert property features (2-5 random features per property)
SELECT p.id, f.feature
FROM properties p
CROSS JOIN LATERAL (
  SELECT feature
  FROM unnest(ARRAY['Bãi đậu xe', 'Sân vườn', 'Hồ bơi', 'Phòng gym', 'An ninh 24/7',
                    'Thang máy', 'Sân thượng', 'Ban công', 'Phòng giặt', 'Phòng làm việc'])
  AS feature
  ORDER BY random()
  LIMIT floor(random() * 4 + 2)::int
) f
WHERE p.id <= 100;

-- Summary
SELECT 'Properties inserted: ' || COUNT(*) FROM properties;
SELECT 'Property images inserted: ' || COUNT(*) FROM property_images;
SELECT 'Property features inserted: ' || COUNT(*) FROM property_features;
